    static int Minutes(string at)=>DateTimeOffset.TryParse(at,out var date)?Math.Max(0,(int)(DateTimeOffset.UtcNow-date).TotalMinutes):0;
    Priority[] Priorities()
    {
        var result=new List<Priority>();foreach(var v in Items("visit").Where(v=>v.S("status")=="open")){
            var id=v.S("id");var units=Items("unit").Where(x=>x.S("visitId")==id).ToArray();var ready=units.Where(x=>x.S("status")=="ready").ToArray();var preparing=units.Where(x=>x.S("status") is "received" or "preparing").ToArray();var pending=Items("notification").Where(x=>x.S("visitId")==id&&!x.B("attended")).ToArray();
            if(ready.Length>0){var wait=ready.Max(x=>Minutes(x.S("readyAt")));result.Add(new(id,"ready","Recoger",ready.Length+" producto"+(ready.Length==1?" listo":"s listos")+" · Hace "+wait+" min",ready.Length,wait));}
            var longest=preparing.Select(x=>Minutes(x.A("history").Objects().LastOrDefault(h=>h.S("status")=="received")?.S("at")??x.S("receivedAt"))).DefaultIfEmpty(0).Max();if(preparing.Length>0&&longest>=state!.Obj("restaurant").L("delayMinutes",15))result.Add(new(id,"delayed","Revisar retraso",longest+" min desde recepción · "+preparing.Length+" en preparación",preparing.Length,longest));
            var unavailable=pending.Where(n=>n.S("type")=="unavailable"&&units.Any(x=>x.S("id")==n.S("unitId")&&x.S("status")=="unavailable")).ToArray();if(unavailable.Length>0)result.Add(new(id,"unavailable","No disponible",unavailable[0].S("message"),unavailable.Length,0));
            if(pending.Any(n=>n.S("type")=="customer"&&n.S("message").Contains("cuenta",StringComparison.OrdinalIgnoreCase)))result.Add(new(id,"bill","Cuenta solicitada","Saldo pendiente de pago",1,0));
            if(pending.Any(n=>n.S("type")=="customer"&&!n.S("message").Contains("cuenta",StringComparison.OrdinalIgnoreCase)))result.Add(new(id,"attention","Solicita atención","Solicitud de la mesa pendiente de atender",1,0));
        }
        return result.OrderBy(p=>p.Kind switch{"ready"=>0,"unavailable"=>1,"delayed"=>2,"bill"=>3,_=>4}).ThenByDescending(p=>p.Minutes).ThenBy(p=>p.VisitId,StringComparer.Ordinal).ToArray();
    }
